-- Editorial profiles for 33 West African publishers (release 2 of the profile gap): 33 publishers (data only, MEDIUM). Generated by Build-Sql.py. Reverse: reverse.sql.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
BEGIN;
CREATE TEMP TABLE prof (publisher_id int, name text, iso text, ownership_type text, owner text, classification_tags text[], political_party_association text,
  historical_context text, current_context text, confidence text, evidence_summary text, evidence_sources jsonb, review_required boolean) ON COMMIT DROP;
DO $$
DECLARE bad int; n int;
BEGIN
  -- Each target must be the active publisher of that name in that country, and must not have a profile yet.
  SELECT count(*) INTO bad FROM prof x
   WHERE NOT EXISTS (SELECT 1 FROM publishers p JOIN countries c ON c.id = p.country_id
                      WHERE p.id = x.publisher_id AND p.name = x.name AND c.iso_code = x.iso AND p.feed_status = 'active')
      OR EXISTS (SELECT 1 FROM editorial_profiles e WHERE e.publisher_id = x.publisher_id);
  IF bad > 0 THEN RAISE EXCEPTION '% of 33 publishers are not the expected outlet or already have a profile - nothing changed', bad; END IF;
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  SELECT publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, DATE '2026-10-16', DATE '2026-10-16', DATE '2026-10-16', review_required FROM prof;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 33 THEN RAISE EXCEPTION 'inserted %, expected 33', n; END IF;
END $$;
SELECT 'profile|' || p.id || '|' || p.name || '|' || array_to_string(e.classification_tags, ',') || '|' || e.confidence || '|review ' || e.review_required
       || '|' || jsonb_array_length(e.evidence_sources) || ' sources'
  FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id WHERE e.publisher_id IN (8882, 8879, 8911, 8904, 8907, 8915, 8892, 8919, 8887, 8917, 8922, 8918, 8910, 8921, 8920, 8878, 8930, 8891, 8956, 8906, 8889, 8936, 8927, 8884, 8880, 8883, 8888, 8902, 8934, 8908, 8925, 8916, 8909) ORDER BY p.id;
SELECT 'gap|' || count(*) || ' active publishers still without a profile'
  FROM publishers p LEFT JOIN editorial_profiles e ON e.publisher_id = p.id WHERE p.feed_status = 'active' AND e.id IS NULL;
COMMIT;
